    "name": "Freccia di cristallo incantata",
    "nameEn": "Enchanted Crystal Arrow",
    "description": "Ashe scaglia un proiettile di ghiaccio in linea retta. Se incontra un campione nemico, infligge danni e lo stordisce. Lo stordimento aumenta con la distanza coperta dal proiettile. Inoltre, le unità vicine al nemico subiscono danni e vengono rallentate.",
