    "slot": "W",
    "name": "Colpo mutilante",
    "nameEn": "Crippling Strike",
    "description": "Il prossimo attacco di Darius colpisce un'arteria vitale del nemico. Mentre sanguina ha la velocità di movimento rallentata.",
    "descriptionEn": "Darius's next attack strikes an enemy's crucial artery. As they bleed out, their Move Speed is slowed.",
    "iconUrl": "https://ddragon.leagueoflegends.com/cdn/16.18.1/img/spell/DariusNoxianTacticsONH.png"
