    "name": "Falce crescente",
    "nameEn": "Crescent Strike",
    "description": "Scatena un impulso di energia lunare in un arco che infligge danni magici.Affligge i nemici colpiti con Luce lunare, rivelandoli per 3 secondi se non sono invisibili.",
    "descriptionEn": "Unleashes a bolt of lunar energy in an arc dealing magic damage.Afflicts enemies struck with Moonlight, revealing them if they are not stealthed for 3 seconds.",
