    "descriptionEn": "Dr. Mundo pumps himself with chemicals, instantly healing a percent of his missing Health. He then gains Move Speed and regenerates a portion of his maximum Health over a long duration.",
    "iconUrl": "https://ddragon.leagueoflegends.com/cdn/16.18.1/img/spell/DrMundoR.png"
