    "name": "Cronodisco",
    "nameEn": "Timewinder",
    "description": "Ekko lancia una granata temporale che esplode, creando un campo di distorsione temporale se colpisce un campione nemico, rallentando e danneggiando tutte le unità nemiche al suo interno. Dopo un periodo di tempo la granata si riavvolge e torna da Ekko, infliggendo danni lungo il percorso.",
    "descriptionEn": "Ekko throws a temporal grenade that expands into a time-distortion field upon hitting an enemy champion, slowing and damaging anyone caught inside. After a delay, the grenade rewinds back to Ekko, dealing damage on its return.",
