    "nameEn": "Cocoon / Rappel",
    "description": "Forma umana: stordisce la prima unità colpita e la rivela se non è invisibile.Forma aracnide: Elise e i suoi Ragnetti si librano in aria e poi si calano sul bersaglio nemico. Dopo aver raggiunto il bersaglio, i danni bonus e la guarigione di Elise in Forma aracnide aumentano.",
    "descriptionEn": "Human Form: Stuns the first enemy unit hit and reveals them if they are not stealthed.Spider Form: Elise and her Spiderlings ascend into the air and then descend upon target enemy. After descending on an enemy target, Elise's bonus damage and healing from Spider Queen is increased.",
