    "descriptionEn": "Hwei envisions a series of torments, allowing him to paint controlling visages.This ability replaces Hwei's abilities with crowd control abilities: Grim Visage, Gaze of the Abyss, and Crushing Maw.",
    "iconUrl": "https://ddragon.leagueoflegends.com/cdn/16.18.1/img/spell/HweiE.png"
