    "name": "Campo di fulmini/Carica iperattiva",
    "nameEn": "Lightning Field / Hyper Charge",
    "description": "Posizione del Martello - Passiva: recupera mana a ogni colpo. Attiva: crea un campo di fulmini che infligge danni ai nemici nelle vicinanze per diversi secondi.Posizione del Cannone: guadagna una carica di energia che aumenta la sua velocità d'attacco al massimo per diversi attacchi.",
    "descriptionEn": "Hammer Stance: Passive: Restores Mana per strike. Active: Creates a field of lightning damaging nearby enemies for several seconds.Cannon Stance: Gains a burst of energy, increasing Attack Speed to maximum for several attacks.",
