    "slot": "E",
    "name": "Colpo tonante/Portale acceleratore",
    "nameEn": "Thundering Blow / Acceleration Gate",
    "description": "Posizione del Martello: infligge danni magici a un nemico e lo respinge a corta distanza.Posizione del Cannone: schiera un Portale acceleratore che aumenta la velocità di movimento di tutti i campioni alleati che vi passano attraverso. Se Esplosione Shock viene lanciata attraverso il portale, velocità, gittata e danni del proiettile aumentano.",
    "descriptionEn": "Hammer Stance: Deals magic damage to an enemy and knocks them back a short distance.Cannon Stance: Deploys an Acceleration Gate increasing the Move Speed of all allied champions who pass through it. If Shock Blast is fired through the gate the missile speed, range, and damage will increase.",
    "iconUrl": "https://ddragon.leagueoflegends.com/cdn/16.18.1/img/spell/JayceThunderingBlow.png"
