    "nameEn": "Mercury Cannon / Mercury Hammer",
    "description": "Posizione del Martello: trasforma il Martello di mercurio nel Cannone di mercurio guadagnando nuove abilità e aumentando la gittata. Il primo attacco in questa posizione riduce l'armatura e la resistenza magica del bersaglio.Posizione del Cannone: trasforma il Cannone di mercurio nel Martello di mercurio guadagnando nuove abilità e aumentando l'armatura e la resistenza magica. Il primo attacco in questa posizione infligge danni magici in più.",
    "descriptionEn": "Hammer Stance: Transforms the Mercury Hammer into the Mercury Cannon gaining new abilities and increased range. The first attack in this form reduces the target's Armor and Magic Resist.Cannon Stance: Transforms the Mercury Cannon into the Mercury Hammer gaining new abilities and increasing Armor and Magic Resist. The first attack in this form deals additional magic damage.",
    "iconUrl": "https://ddragon.leagueoflegends.com/cdn/16.18.1/img/spell/JayceStanceHtG.png"
