    "name": "Balzo",
    "nameEn": "Leap",
    "description": "Kha'Zix balza in un'area, infliggendo danni fisici all'impatto. Se sceglie Evoluzione: Ali, la distanza del Balzo aumenta di 200 e la ricarica si azzera all'uccisione di campioni o con gli assist.",
