    "name": "Assalto del Vuoto",
    "nameEn": "Void Assault",
    "description": "Ogni livello permette a Kha'Zix di evolvere una delle sue abilità, dandogli un effetto aggiuntivo unico. Quando è attivo, Kha'Zix diventa invisibile, attivando Minaccia celata e aumentando la velocità di movimento. Se sceglie Evoluzione: Mimetismo dinamico, la durata dell'invisibilità di Assalto del Vuoto aumenta e ha un uso aggiuntivo.",
    "descriptionEn": "Each rank allows Kha'Zix to evolve one of his abilities, giving it a unique additional effect. When activated, Kha'Zix becomes Invisible, triggering Unseen Threat and increasing Move Speed. If he chooses to Evolve Adaptive Cloaking, Void Assault gains increased Invisibility duration, and an additional use.",
