    "name": "Stile innato",
    "nameEn": "Inherent Glamour",
    "description": "Neeko può assumere l'aspetto di un campione alleato o di altre unità sulla mappa. Il camuffamento cessa quando subisci effetti di controllo immobilizzanti, lanci abilità con danni, danneggi una torre nemica con l'aspetto di un non campione o subisci danni pari alla salute dell'unità di cui hai preso le sembianze.",
