    "descriptionEn": "While in Brush, Rengar leaps at his target with his basic attack.Rengar generates Ferocity whenever he casts an ability. At Max Ferocity, his next ability is empowered.Killing enemy champions awards trophies on Rengar's Bonetooth Necklace, granting bonus attack damage.",
    "iconUrl": "https://ddragon.leagueoflegends.com/cdn/16.18.1/img/passive/Rengar_P.png"
