    "nameEn": "Junkyard Titan",
    "description": "Ogni abilità che Rumble lancia gli dà Calore. Quando raggiunge il 50% di Calore, si trova nella Zona pericolosa, che conferisce a tutte le sue abilità degli effetti bonus. Quando raggiunge il 100% di Calore, inizia il Surriscaldamento, ottiene velocità d'attacco bonus e infligge danni bonus con i suoi attacchi base, ma non può lanciare abilità per alcuni secondi.",
    "descriptionEn": "Every spell Rumble casts gives him Heat. When he reaches 50% Heat he reaches Danger Zone, granting all his basic abilities bonus effects. When he reaches 100% Heat, he starts Overheating, gaining bonus Attack Speed and granting his basic attacks bonus damage, but making him unable to cast spells for a few seconds.",
    "iconUrl": "https://ddragon.leagueoflegends.com/cdn/16.18.1/img/passive/Rumble_JunkyardTitan1.png"
