    "name": "Mano della morte",
    "nameEn": "Death's Hand",
    "description": "Swain scatena vari dardi di potere infernale che attraversano i nemici. I nemici subiscono più danni per ogni dardo che li colpisce.",
    "descriptionEn": "Swain unleashes several bolts of eldritch power that pierce through enemies. Enemies hit take more damage for each bolt they are struck by.",
