    "name": "Visione dell'impero",
    "nameEn": "Vision of Empire",
    "description": "Swain apre un occhio demoniaco che infligge danni e rallenta i nemici. I campioni colpiti vengono rivelati e conferiscono a Swain un frammento d'anima.",
    "descriptionEn": "Swain opens a demon eye that deals damage and slows enemies. Champions hit are revealed and also grant Swain a Soul Fragment.",
