    "description": "I nemici che muoiono davanti a Viego diventano spettri. Attaccando uno spettro Viego può prendere temporaneamente il controllo del cadavere del nemico, curandosi per una percentuale della salute massima del bersaglio e ottenendo accesso ai suoi oggetti e alle sue abilità di base. La suprema del bersaglio viene sostituita con un lancio gratuito della suprema di Viego.",
    "descriptionEn": "Enemies who fall before Viego become wraiths. By attacking a wraith, Viego temporarily seizes control of the dead enemy's body, healing for a percentage of his target's max health and gaining access to their basic abilities and items. He replaces their Ultimate with a free cast of his own.",
