    "name": "Divisione cellulare",
    "nameEn": "Cell Division",
    "description": "Ogni volta che Zac colpisce un nemico con un'abilità, lascia cadere un pezzo di se stesso che può essere riassorbito per recuperare salute. Quando subisce danni fatali, Zac si divide in 4 masse che cercano di ricombinarsi. Se le masse sono intatte, torna in vita con una quantità di salute proporzionale a quella delle masse sopravvissute. Ogni massa ha una percentuale della salute massima, dell'armatura e della resistenza magica di Zac. L'abilità ha 5 minuti di ricarica.",
    "descriptionEn": "Each time Zac hits an enemy with an ability, he sheds a chunk of himself that can be reabsorbed to restore Health. Upon taking fatal damage, Zac splits into 4 bloblets that attempt to recombine. If any bloblets remain, he will revive with an amount of Health depending on the Health of the surviving bloblets. Each bloblet has a percentage of Zac's maximum Health, Armor and Magic Resistance. This ability has a 5 minute cooldown.",
